package com.slss.domain;
import jakarta.persistence.*;
@Entity @Table(name="asset_components") public class AssetComponent { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="asset_id",nullable=false) Asset asset; @Column(name="component_type",nullable=false) String componentType; String model; @Column(name="serial_no",nullable=false,unique=true) String serialNo; @Column(name="fault_description",columnDefinition="TEXT") String faultDescription; public Long getId(){return id;} public Asset getAsset(){return asset;} public String getComponentType(){return componentType;} public String getModel(){return model;} public String getSerialNo(){return serialNo;} public String getFaultDescription(){return faultDescription;} public void setAsset(Asset a){asset=a;} public void setComponentType(String v){componentType=v;} public void setModel(String v){model=v;} public void setSerialNo(String v){serialNo=v;} public void setFaultDescription(String v){faultDescription=v;} }
